def apply(inputs, premises):
    n = min(len(inputs["item_lengths"]), len(inputs["item_widths"]), len(inputs["item_heights"]), len(inputs["item_weights"]))
    personal_used = 0
    carryon_used = 0
    checked_count = 0
    total = inputs["ticket_price"]
    for i in range(n):
        personal_fit = inputs["item_lengths"][i] <= inputs["personal_item_limits"][0] and inputs["item_widths"][i] <= inputs["personal_item_limits"][1] and inputs["item_heights"][i] <= inputs["personal_item_limits"][2]
        carryon_fit = inputs["item_lengths"][i] <= inputs["carryon_limits"][0] and inputs["item_widths"][i] <= inputs["carryon_limits"][1] and inputs["item_heights"][i] <= inputs["carryon_limits"][2]
        cabin_item = False
        if personal_fit and personal_used < inputs["personal_item_allowance"]:
            personal_used = personal_used + 1
            cabin_item = True
        elif carryon_fit and carryon_used < inputs["carryon_allowance"]:
            carryon_used = carryon_used + 1
            cabin_item = True
        if not cabin_item:
            base_index = min(checked_count, len(inputs["checked_bag_base_fees"]) - 1)
            base_fee = inputs["checked_bag_base_fees"][base_index]
            checked_count = checked_count + 1
            overweight_fee = 0
            if inputs["item_weights"][i] > inputs["standard_weight_limit"]:
                tier_count = min(len(inputs["overweight_upper_bounds"]), len(inputs["overweight_fees"]))
                for j in range(tier_count):
                    if inputs["item_weights"][i] <= inputs["overweight_upper_bounds"][j]:
                        overweight_fee = inputs["overweight_fees"][j]
                        break
            linear_size = inputs["item_lengths"][i] + inputs["item_widths"][i] + inputs["item_heights"][i]
            oversize_fee = 0
            if linear_size > inputs["standard_linear_size_limit"]:
                tier_count = min(len(inputs["oversize_upper_bounds"]), len(inputs["oversize_fees"]))
                for j in range(tier_count):
                    if linear_size <= inputs["oversize_upper_bounds"][j]:
                        oversize_fee = inputs["oversize_fees"][j]
                        break
            total = total + base_fee + max(overweight_fee, oversize_fee)
    return {"answer": int(round(total))}

